import React,{useEffect,useMemo,useState}from'react';
import { createPortal } from 'react-dom';
import {Html5Qrcode} from 'html5-qrcode';
import{Routes,Route,Link,Navigate,useNavigate,useParams,useLocation}from'react-router-dom';
import{Search,ShoppingBag,Store,Clock,MapPin,ArrowRight,LogOut,TrendingUp,ClipboardList,Plus,Minus,Trash2,CheckCircle2,Utensils,Wallet,Download,ScanLine,ChevronRight,FileText,Upload,ImagePlus,WandSparkles,Beef,Fish,Leaf,Coffee,Wheat,Droplets,Flame,Timer,X,ChefHat,ShieldCheck,Users,Building2,Activity,UserPlus,Power,RefreshCw,AlertTriangle}from'lucide-react';
import{request,uploadFile,money,imageForFood,imageForShop,API_ORIGIN}from'./api';
const Auth=React.createContext(null),Cart=React.createContext(null);
function useAuth(){return React.useContext(Auth)}function useCart(){return React.useContext(Cart)}
function App(){const[user,setUser]=useState(null),[loading,setLoading]=useState(true),[cart,setCart]=useState([]);useEffect(()=>{if(localStorage.getItem('ms_token'))request('/auth/me').then(setUser).catch(()=>localStorage.removeItem('ms_token')).finally(()=>setLoading(false));else setLoading(false)},[]);const logout=()=>{localStorage.removeItem('ms_token');setUser(null);setCart([])};const auth={user,setUser,logout};const cartCtx={cart,setCart};if(loading)return <div className="min-h-screen grid place-items-center text-brand-600 font-bold">Loading MealSync…</div>;return <Auth.Provider value={auth}><Cart.Provider value={cartCtx}><Routes><Route path="/login" element={user?<Navigate to="/" replace/>:<Login/>}/><Route path="/*" element={user?<Shell/>:<Navigate to="/login" replace/>}/></Routes></Cart.Provider></Auth.Provider>}
function Login(){
 const {setUser}=useAuth(),[email,setEmail]=useState('student@mealsync.test'),[password,setPassword]=useState('student123'),[error,setError]=useState(''),[busy,setBusy]=useState(false),[showDemo,setShowDemo]=useState(false),nav=useNavigate();
 async function submit(e){e.preventDefault();setBusy(true);setError('');try{const d=await request('/auth/login',{method:'POST',body:JSON.stringify({email,password})});localStorage.setItem('ms_token',d.token);setUser(d.user);nav('/')}catch(e){setError(e.message)}finally{setBusy(false)}}
 const vendors=[['Chinese','chinese@mealsync.test'],['Fast Food','fastfood@mealsync.test'],['Kopitiam','kopitiam@mealsync.test'],['Japanese & Korean','japanese@mealsync.test'],['Mamak','mamak@mealsync.test'],['Shawarma','shawarma@mealsync.test'],['Asian Cuisine','asian@mealsync.test'],['Picante','picante@mealsync.test']];
 return <div className="auth-screen"><div className="auth-orb auth-orb-one"/><div className="auth-orb auth-orb-two"/><section className="auth-showcase"><div className="auth-brand"><div className="auth-wordmark">mealsync<span>®</span></div><span>APU CAMPUS FOOD PLATFORM</span></div><div className="auth-showcase-copy"><span className="auth-kicker">YOUR CAMPUS. YOUR CRAVINGS.</span><h1>Good food,<br/><em>minus the wait.</em></h1><p>Discover campus favourites, order ahead and collect your meal when it is ready.</p><div className="auth-feature-row"><span><ShoppingBag size={16}/> Order ahead</span><span><Clock size={16}/> Live updates</span><span><CheckCircle2 size={16}/> Easy pickup</span></div></div><div className="auth-showcase-bottom"><span>MEALSYNC · ASIA PACIFIC UNIVERSITY</span><span>Made for campus life <span className="auth-heart">✦</span></span></div></section><section className="auth-panel"><form onSubmit={submit} className="auth-form"><div className="auth-mobile-brand"><img src="/mealsync-logo.svg"/></div><span className="eyebrow">WELCOME BACK</span><h2>Sign in to MealSync</h2><p className="auth-subtitle">Your next campus meal is just a few clicks away.</p><label>Email address</label><input className="field" type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com" required/><label>Password</label><input className="field" type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="Enter your password" required/>{error&&<div className="auth-error">{error}</div>}<button disabled={busy} className="btn btn-primary auth-submit">{busy?'Signing you in…':'Continue to MealSync'}<ArrowRight size={17}/></button><button type="button" className="auth-demo-toggle" onClick={()=>setShowDemo(v=>!v)}>{showDemo?'Hide':'Show'} demo accounts <ChevronRight size={15}/></button>{showDemo&&<div className="auth-demo-list"><button type="button" onClick={()=>{setEmail('admin@mealsync.test');setPassword('admin123')}}><b>Admin workspace</b><small>admin@mealsync.test</small></button><button type="button" onClick={()=>{setEmail('student@mealsync.test');setPassword('student123')}}><b>Student workspace</b><small>student@mealsync.test</small></button>{vendors.map(([name,mail])=><button type="button" key={mail} onClick={()=>{setEmail(mail);setPassword('vendor123')}}><b>{name} vendor</b><small>{mail}</small></button>)}<p>Admin password: admin123 · Student password: student123 · Vendor password: vendor123</p></div>}<p className="auth-security"><span/> Secure sign-in · Demo environment</p></form></section></div>
}
function Shell(){
 const{user,logout}=useAuth(),loc=useLocation();
 const admin=user.role==='admin',vendor=user.role==='vendor';
 return <div className="app-shell">
  <header className="nav"><div className="nav-inner">
   <Link to="/"><img src="/mealsync-logo.svg" className="w-32"/></Link>
   <nav className="nav-links">
    {admin?<Nav to="/" icon={<ShieldCheck size={16}/>} label="Admin centre"/>:
    vendor?<><Nav to="/" icon={<TrendingUp size={16}/>} label="Overview"/><Nav to="/vendor/orders" icon={<ClipboardList size={16}/>} label="Live orders"/><Nav to="/vendor/menu" icon={<Utensils size={16}/>} label="Menu"/><Nav to="/vendor/finance" icon={<Wallet size={16}/>} label="Finance"/><Nav to="/vendor/feedback" icon={<CheckCircle2 size={16}/>} label="Feedback"/></>:
    <><Nav to="/" icon={<Store size={16}/>} label="Home"/><Nav to="/shops" icon={<Utensils size={16}/>} label="Shops"/><Nav to="/orders" icon={<ClipboardList size={16}/>} label="Orders"/><Nav to="/spending" icon={<Wallet size={16}/>} label="Spending"/><CartNav/></>}
   </nav>
   <div className="flex items-center gap-3 ml-3"><span className="hidden sm:block text-xs font-bold text-slate-500">{user.name.split(' ')[0]}</span><button onClick={logout} className="btn btn-outline !p-2" title="Sign out"><LogOut size={17}/></button></div>
  </div></header>
  <div className="page-transition" key={loc.pathname}>
   <Routes>
    {admin?<><Route path="/" element={<AdminDashboard/>}/><Route path="/admin/vendors" element={<Navigate to="/" replace/>}/><Route path="*" element={<Navigate to="/" replace/>}/></>:
    vendor?<><Route path="/" element={<VendorDashboard/>}/><Route path="/vendor/orders" element={<VendorOrders/>}/><Route path="/vendor/menu" element={<VendorMenu/>}/><Route path="/vendor/finance" element={<VendorFinance/>}/><Route path="/vendor/feedback" element={<VendorFeedback/>}/><Route path="/vendor/settings" element={<Navigate to="/" replace/>}/><Route path="/vendor/reports" element={<Reports/>}/><Route path="*" element={<Navigate to="/" replace/>}/></>:
    <><Route path="/" element={<StudentHome/>}/><Route path="/shops" element={<Shops/>}/><Route path="/shops/:id" element={<ShopDetail/>}/><Route path="/food/:id" element={<FoodDetail/>}/><Route path="/cart" element={<CartPage/>}/><Route path="/orders" element={<StudentOrders/>}/><Route path="/orders/:id" element={<OrderDetail/>}/><Route path="/spending" element={<Spending/>}/><Route path="*" element={<Navigate to="/" replace/>}/></>}
   </Routes>
  </div>
 </div>
}
function Nav({to,icon,label}){const loc=useLocation();return <Link className={loc.pathname===to?'active':''} to={to}><span className="hidden md:inline-flex mr-1">{icon}</span>{label}</Link>}
function CartNav(){const{cart}=useCart(),loc=useLocation();const count=cart.reduce((n,item)=>n+Math.max(0,Number(item.quantity)||1),0);const label=count>99?'99+':String(count);return <Link to="/cart" className={`cart-nav-link ${loc.pathname==='/cart'?'active':''}`}><span className="hidden md:inline-flex mr-1"><ShoppingBag size={16}/></span>Cart<span className={`cart-count ${count?'has-items':''}`}>{label}</span></Link>}
function Head({kicker,title,desc,action}){return <div className="section-head"><div><span className="eyebrow">{kicker}</span><h2>{title}</h2>{desc&&<p className="muted text-sm">{desc}</p>}</div>{action}</div>}
function StudentHome(){const[home,setHome]=useState(null),[q,setQ]=useState(''),[results,setResults]=useState(null);useEffect(()=>{request('/home').then(setHome)},[]);async function search(e){e.preventDefault();if(!q.trim()){setResults(null);return}const[f,s]=await Promise.all([request('/foods?q='+encodeURIComponent(q)),request('/shops?q='+encodeURIComponent(q))]);setResults({foods:f,shops:s})}return <main className="page-wrap fade-up"><section className="hero"><span className="text-blue-200 text-xs font-extrabold tracking-widest">MEALSYNC · APU CAMPUS</span><h1>What are you craving<br/>today?</h1><p>Explore campus menus, discover new favourites and order ahead for easy pickup.</p><form onSubmit={search} className="hero-search"><Search className="text-slate-400 ml-3 self-center"/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search food, cuisine or campus shop…"/><button className="btn btn-primary">Search <ArrowRight size={16}/></button></form></section>{results&&<><Head kicker="SEARCH RESULTS" title={`Results for “${q}”`}/><h3 className="font-bold mb-3">Related foods ({results.foods.length})</h3><FoodGrid foods={results.foods}/><h3 className="font-bold mt-7 mb-3">Related shops ({results.shops.length})</h3><ShopGrid shops={results.shops}/></>}{home&&<><Head kicker="FIND YOUR FAVOURITE" title="Explore campus shops" desc="Browse the food spots around your campus." action={<Link className="text-brand-600 font-bold text-sm" to="/shops">All shops <ArrowRight className="inline" size={15}/></Link>}/><ShopGrid shops={home.shops}/><Head kicker="STUDENT FAVOURITES" title="Popular on campus" desc="A selection of dishes to get your appetite going." action={<Link to="/shops" className="text-brand-600 font-bold text-sm">Explore menu <ArrowRight className="inline" size={15}/></Link>}/><FoodGrid foods={home.popular}/></>}</main>}
function ShopGrid({shops=[]}){return <div className="grid-shops">{shops.map(s=><Link key={s.id} to={`/shops/${s.id}`} className="card p-3 hover:-translate-y-1 hover:shadow-soft"><img src={s.image_url||imageForShop(s)} className="shop-img" /><div className="p-2"><div className="flex justify-between gap-2"><h3 className="font-extrabold text-lg">{s.name}</h3><span className={s.is_open?'pill':'status cancelled'}>{s.is_open?'Open':'Closed'}</span></div><p className="muted text-sm mt-2 line-clamp-2">{s.description}</p><p className="text-xs text-slate-500 mt-3"><Clock className="inline mr-1" size={14}/>08:00 – 18:00</p></div></Link>)}</div>}
function FoodGrid({foods=[]}){const{cart,setCart}=useCart();const tagIcon=(t)=>({chicken:<Beef size={12}/>,beef:<Beef size={12}/>,fish:<Fish size={12}/>,seafood:<Fish size={12}/>,vegetarian:<Leaf size={12}/>,veg:<Leaf size={12}/>,beverages:<Coffee size={12}/>,western:<Wheat size={12}/>,asian:<Wheat size={12}/>,"non-veg":<Flame size={12}/>}[t]||null);return <div className="grid-food">{foods.map(f=><article key={f.id} className="card food-tile"><Link to={`/food/${f.id}`}><div className="food-photo"><img className="food-img" src={f.image_url||imageForFood(f)} alt={f.name}/>{f.todays_special?<span className="food-ribbon">Today’s special</span>:null}</div><div className="pt-3"><span className="text-[10px] font-extrabold uppercase tracking-wider text-brand-600">{f.category||'Campus favourite'}</span><h3 className="font-extrabold mt-1">{f.name}</h3><p className="muted text-xs mt-1">{f.shop_name}</p><p className="text-xs text-slate-500 mt-2 line-clamp-2">{f.description}</p><div className="food-tags">{(f.tags||[]).slice(0,4).map(t=><span key={t}>{tagIcon(t)}{t}</span>)}</div></div></Link><div className="flex justify-between items-center mt-3"><strong>{money(f.price_sen)}</strong><Link to={`/food/${f.id}`} className="btn btn-light !p-2" title="Customise"><Plus size={17}/></Link></div></article>)}</div>}

function FoodDetail(){const{id}=useParams(),[food,setFood]=useState(null),[qty,setQty]=useState(1),[selected,setSelected]=useState([]),[notes,setNotes]=useState(''),[added,setAdded]=useState(false);const{cart,setCart}=useCart();useEffect(()=>{request('/foods/'+id).then(setFood)},[id]);if(!food)return <main className="page-wrap">Loading food…</main>;const addons=food.addons||[];const chosen=addons.filter(a=>selected.includes(a.id));const addonTotal=chosen.reduce((sum,a)=>sum+Number(a.price_sen||0),0);const total=(Number(food.price_sen)+addonTotal)*qty;const n=food.nutrition||{};const nutrition={calories:Number(n.calories||520)+chosen.length*45,protein_g:Number(n.protein_g||24)+chosen.length*2,carbs_g:Number(n.carbs_g||58)+chosen.length*5,fat_g:Number(n.fat_g||19)+chosen.length*2};const tags=food.tags||[];const add=()=>{setCart([...cart,{...food,quantity:qty,addon_ids:selected,tray_food_ids:[],notes,cart_key:crypto.randomUUID()}]);setAdded(true);setTimeout(()=>setAdded(false),2200)};return <main className="page-wrap fade-up"><Link to={`/shops/${food.shop_id}`} className="text-brand-600 font-bold text-sm">← Back to {food.shop_name}</Link><div className="food-detail-layout mt-5"><div className="space-y-5"><div className="food-detail-image"><img src={imageForFood(food)} alt={food.name}/><div className="food-image-caption"><span>{food.shop_name}</span><span>{food.category||'Menu favourite'}</span></div></div><section className="card p-6 nutrition-card"><div className="flex items-center justify-between gap-3"><div><span className="eyebrow">A LITTLE FOOD INSIGHT</span><h3 className="font-extrabold text-xl mt-1">Nutritional estimate</h3></div><span className="estimate-pill">Per serving</span></div><p className="muted text-xs mt-2">Updates as you select add-ons. Values are illustrative estimates, not verified vendor nutrition data.</p><div className="nutrition-grid mt-5">{[[Flame,'Calories',nutrition.calories,'kcal'],[Beef,'Protein',nutrition.protein_g,'g'],[Wheat,'Carbs',nutrition.carbs_g,'g'],[Droplets,'Fat',nutrition.fat_g,'g']].map(([Icon,label,value,unit])=><div className="nutrition-stat" key={label}><span><Icon size={17}/></span><strong>{Math.round(value)}<small>{unit}</small></strong><label>{label}</label></div>)}</div><div className="nutrition-note">{chosen.length?`Nutrition estimate includes ${chosen.length} selected add-on${chosen.length>1?'s':''}.`:'Select add-ons to see the estimate adjust.'}</div></section></div><section className="card food-config"><span className="eyebrow">{food.shop_name} · CUSTOMISE YOUR MEAL</span><h1 className="font-display text-3xl font-extrabold mt-2">{food.name}</h1><p className="muted mt-3 leading-7">{food.description}</p><div className="flex flex-wrap gap-2 mt-4">{tags.map(t=><span className="food-tag-large" key={t}>{t}</span>)}</div><div className="price-live-row"><div><span className="muted text-xs">Base price</span><strong>{money(food.price_sen)}</strong></div><div className="text-right"><span className="muted text-xs">Your total</span><strong className="live-price">{money(total)}</strong></div></div>{addons.length>0&&<><div className="config-divider"/><div className="flex justify-between items-end"><div><h3 className="font-extrabold text-lg">Make it yours</h3><p className="muted text-xs mt-1">Optional extras · price updates instantly</p></div><span className="estimate-pill">{selected.length} selected</span></div><div className="addon-list">{addons.map((a,i)=><label key={a.id} className={`addon-option ${selected.includes(a.id)?'selected':''}`}><span className="addon-check"><input type="checkbox" checked={selected.includes(a.id)} onChange={e=>setSelected(e.target.checked?[...selected,a.id]:selected.filter(v=>v!==a.id))}/></span><span className="addon-copy"><b>{a.name}</b><small>{a.description||'Add a little extra to your meal'}</small></span><strong>+{money(a.price_sen)}</strong></label>)}</div></>}<label className="font-bold text-sm block mt-6">Special instructions</label><textarea className="field mt-2" rows="3" maxLength="240" placeholder="Less spicy, sauce on the side…" value={notes} onChange={e=>setNotes(e.target.value)}/><div className="flex justify-between items-center mt-5"><div className="quantity-control"><button type="button" onClick={()=>setQty(Math.max(1,qty-1))}><Minus size={16}/></button><b>{qty}</b><button type="button" onClick={()=>setQty(Math.min(30,qty+1))}><Plus size={16}/></button></div><button onClick={add} className="btn btn-primary add-order-btn">Add to order · {money(total)} <ShoppingBag size={17}/></button></div></section></div>{added&&<div className="toast-success" role="status"><CheckCircle2 size={19}/> Added to your cart <Link to="/cart" className="font-extrabold underline ml-2">View cart</Link></div>}</main>}
function Shops(){const[shops,setShops]=useState([]),[q,setQ]=useState('');useEffect(()=>{request('/shops').then(setShops)},[]);const filtered=shops.filter(s=>s.name.toLowerCase().includes(q.toLowerCase()));return <main className="page-wrap fade-up"><Head kicker="THE CAMPUS FOOD GUIDE" title="Find your next favourite" desc="Explore the campus kitchens, browse menus and choose what sounds good."/><div className="card p-3 mb-6 flex gap-3 items-center"><Search className="text-slate-400 ml-2"/><input className="outline-none flex-1 min-w-0" placeholder="Search campus shops…" value={q} onChange={e=>setQ(e.target.value)}/></div><ShopGrid shops={filtered}/></main>}
function LunchSetBuilder({shop,foods}){
 const [quantities,setQuantities]=useState({}),[query,setQuery]=useState(''),{cart,setCart}=useCart();
 const visible=foods.filter(f=>[f.name,f.description,f.category].join(' ').toLowerCase().includes(query.toLowerCase()));
 const chosen=foods.filter(f=>Number(quantities[f.id]||0)>0);
 const count=chosen.reduce((n,f)=>n+Number(quantities[f.id]||0),0);
 const total=chosen.reduce((sum,f)=>sum+Number(f.price_sen||0)*Number(quantities[f.id]||0),0);

 // Illustrative per-portion estimates. Prefer actual nutrition values if supplied by the food record.
 const estimateFor=(food)=>{
  const n=food.nutrition||{};
  const name=(food.name||'').toLowerCase();
  let base={calories:180,protein_g:7,carbs_g:24,fat_g:6};
  if(/rice|nasi/.test(name)) base={calories:210,protein_g:4,carbs_g:46,fat_g:1};
  if(/chicken|ayam|fish|ikan|pork|beef|tofu|egg|telur/.test(name)) base={calories:230,protein_g:20,carbs_g:8,fat_g:12};
  if(/curry|kari|sambal/.test(name)) base={calories:160,protein_g:5,carbs_g:12,fat_g:10};
  if(/vegetable|cabbage|kangkung|sayur/.test(name)) base={calories:90,protein_g:3,carbs_g:10,fat_g:4};
  return {
   calories:Number(n.calories??base.calories),
   protein_g:Number(n.protein_g??base.protein_g),
   carbs_g:Number(n.carbs_g??base.carbs_g),
   fat_g:Number(n.fat_g??base.fat_g)
  };
 };
 const nutrition=chosen.reduce((sum,f)=>{
  const q=Number(quantities[f.id]||0),n=estimateFor(f);
  return {
   calories:sum.calories+n.calories*q,
   protein_g:sum.protein_g+n.protein_g*q,
   carbs_g:sum.carbs_g+n.carbs_g*q,
   fat_g:sum.fat_g+n.fat_g*q
  };
 },{calories:0,protein_g:0,carbs_g:0,fat_g:0});

 function changeQty(id,next){setQuantities(prev=>({...prev,[id]:Math.max(0,Math.min(20,next))}));}
 function addSet(){
  if(!chosen.length)return;
  const first=chosen[0];
  const firstQty=Number(quantities[first.id]||0);
  const extraIds=[],names=[];
  chosen.forEach(f=>{
   const q=Number(quantities[f.id]||0);
   for(let n=0;n<q;n++) names.push(f.name);
   for(let n=0;n<q-(f.id===first.id?1:0);n++) extraIds.push(f.id);
  });
  setCart([...cart,{
   ...first,
   name:`${shop.name} Lunch Set`,
   description:names.join(' · '),
   quantity:1,
   addon_ids:[],
   tray_food_ids:extraIds,
   tray_food_total_sen:total-Number(first.price_sen||0),
   lunch_set_names:names,
   nutrition,
   notes:'',
   cart_key:crypto.randomUUID()
  }]);
  setQuantities({});
 }
 return <section className={`lunch-set-feature lunch-${shop.name.toLowerCase().replace(/[^a-z0-9]+/g,'-')}`}>
  <div className="lunch-feature-head">
   <div>
    <span className="lunch-feature-kicker">BUILD A COMPLETE MEAL</span>
    <h2>{shop.name} Lunch Set</h2>
    <p>Choose how many portions of each tray favourite you want. Your total updates as you build.</p>
   </div>
   <div className="lunch-feature-badge"><b>{foods.length}</b><small>tray choices</small></div>
  </div>
  <div className="lunch-builder-body">
   <div className="lunch-builder-main">
    <div className="lunch-builder-tools">
     <b>Choose your dishes</b>
     <label><Search size={15}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Find a tray dish…"/></label>
    </div>
    <div className="lunch-choice-grid">
     {visible.map(f=>{
      const qty=Number(quantities[f.id]||0);
      return <article key={f.id} className={`lunch-choice-card ${qty?'selected':''}`}>
       <img src={imageForFood(f)} alt=""/>
       <span className="lunch-choice-info">
        <b>{f.name}</b><small>{f.description}</small><strong>{money(f.price_sen)} each</strong>
       </span>
       <div className="lunch-qty-control">
        <button type="button" aria-label={`Remove one ${f.name}`} disabled={!qty} onClick={()=>changeQty(f.id,qty-1)}>−</button>
        <b>{qty}</b>
        <button type="button" aria-label={`Add one ${f.name}`} onClick={()=>changeQty(f.id,qty+1)}>+</button>
       </div>
      </article>;
     })}
    </div>
    {!visible.length&&<p className="muted text-sm py-5">No tray dishes match that search.</p>}
   </div>
   <aside className="lunch-builder-summary">
    <span className="eyebrow">YOUR PLATE</span>
    <div className="lunch-selected-count"><strong>{count}</strong><span>portions selected</span></div>
    <div className="lunch-selected-list">
     {chosen.length?chosen.map(f=><div key={f.id}><span>{f.name} × {quantities[f.id]}</span><b>{money(Number(f.price_sen||0)*Number(quantities[f.id]||0))}</b></div>):<p>Use + and − to choose your portions.</p>}
    </div>
    <div className="lunch-total-line"><span>Set total</span><strong><RollingValue value={money(total)}/></strong></div>
    <button className="btn btn-primary w-full" disabled={!count} onClick={addSet}>Add lunch set <ShoppingBag size={16}/></button>
    <small className="lunch-summary-note">You can still order tray dishes individually below.</small>

    <div className="lunch-nutrition">
     <div className="lunch-nutrition-heading">
      <div><span className="eyebrow">NUTRITION ESTIMATE</span><b>What’s on your plate</b></div>
      <span>Live</span>
     </div>
     <div className="lunch-nutrition-grid">
      <div><strong>{Math.round(nutrition.calories)}</strong><small>kcal</small><label>Calories</label></div>
      <div><strong>{Math.round(nutrition.protein_g)}<small>g</small></strong><label>Protein</label></div>
      <div><strong>{Math.round(nutrition.carbs_g)}<small>g</small></strong><label>Carbs</label></div>
      <div><strong>{Math.round(nutrition.fat_g)}<small>g</small></strong><label>Fat</label></div>
     </div>
     <p>Updates as you change portions. Values are illustrative estimates, not verified vendor nutrition data.</p>
    </div>
   </aside>
  </div>
 </section>
}
