 useEffect(()=>{load();const t=setInterval(()=>{if(!document.hidden)load()},15000);return()=>clearInterval(t)},[]);
 const c=data?.counts||{},active=vendors.filter(v=>v.is_active),disabled=vendors.filter(v=>!v.is_active),visible=vendors.filter(v=>[v.name,v.email,v.shop_name].join(' ').toLowerCase().includes(query.toLowerCase()));
 async function create(e){e.preventDefault();setBusy(true);setError('');setNotice('');try{await request('/admin/vendors',{method:'POST',body:JSON.stringify(form)});setNotice('Vendor account created. The new shop starts closed until the vendor is ready.');setForm({name:'',email:'',password:'',shop_name:'',shop_description:''});setShowForm(false);await load();setTab('vendors')}catch(e){setError(e.message)}finally{setBusy(false)}}
