 const active=foods.filter(f=>f.food_type!=='addons'&&f.active!==0);const lunchSetShop=['SHOP001','SHOP005'].includes(foods[0]?.shop_id);const cats=[...new Set(active.map(f=>f.category||'Other'))].sort();const visible=active.filter(f=>(filter==='all'||(filter==='available'?!!f.available:!f.available))&&(category==='all'||(f.category||'Other')===category)&&(`${f.name} ${f.description} ${f.category}`.toLowerCase().includes(query.toLowerCase())));
